    if(!st.lvl||!st.on||onFire(b.id)||brk){bstat[b.id]={f:0,lim:null,speed:st.lvl?bSpeed(b.id):0,fire:onFire(b.id),broke:brk};continue;}
    const sp=bSpeed(b.id); active.push([b,sp]); const mi=bInMult(b.id);
