    for(let z=2;z<z1-2;z+=2.4){const p=fq(f,K,fA(B,f,q0+.02),fA(B,f,q1-.02),z,z);ctx.moveTo(p[0][0],p[0][1]);ctx.lineTo(p[1][0],p[1][1]);}ctx.stroke();
