      const h=hash2(i+50,j+50), lane=laneTile(i,j);
      let c=lane?(((i+j)&1)?'#d3cdbf':'#cbc4b4'):(((i+j)&1)?'#dcc598':'#d6be8f');
      if(!lane&&h>.86) c='#d1b886';
