  const ep=P(di+.8,dj,10);ell(ctx,ep[0],ep[1],5,5.5,'#2f6f9a');ell(ctx,ep[0],ep[1],2,2.2,'#1a3a5a');
  if(S.collectors.lumberjack>0&&Math.random()<scene.dtF*4){emitP(ep[0]+3,ep[1],'bark');}
