  ctx.strokeStyle='#7a828a';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(x-9,yy-3);ctx.lineTo(x+9,yy+3);ctx.moveTo(x+9,yy-3);ctx.lineTo(x-9,yy+3);ctx.stroke();
