  ctx.save();fxf(ctx,'J',j1,(i0+i1)/2,H-3.5);ctx.fillStyle='#fff';ctx.font='900 4.6px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(l>=PW_MAX?'★ TIMBER POWER ★':'TIMBER POWER',0,0);ctx.restore();
