  ctx.strokeStyle='rgba(255,255,255,.35)';ctx.lineWidth=.5;ctx.beginPath();{const p=P(C[1][0],C[1][1],3),q=P(C[1][0],C[1][1],H);ctx.moveTo(p[0]+.5,p[1]);ctx.lineTo(q[0]+.5,q[1]);}ctx.stroke();
