  {const p=P(ci+.11,cj,H-1.6),q=P(ci,cj+.11,H-1.6);ctx.fillStyle='#9fd0e6';ctx.fillRect(p[0]-2.5,p[1]-2,2.6,2.6);ctx.fillRect(q[0],q[1]-2,2.6,2.6);}
  // tower head (A-frame) + pendants
