  const cands=[[lx,bot-h]];
  for(const r of avoid){cands.push([lx,Math.round(r.top-8-h)]);cands.push([lx,Math.round(r.bottom+8)]);}
  cands.push([lx,top]);if(!phone) cands.push([W-w-10,top+60]);
